<?php
namespace App\Http\Controllers\Api;
use App\Http\Controllers\Controller; use App\Models\Business; use Illuminate\Http\JsonResponse; use Illuminate\Http\Request; use Illuminate\Support\Facades\Http; use Illuminate\Validation\ValidationException;
class WebsiteCheckController extends Controller {
 public function __invoke(Request $r,string $business):JsonResponse{$b=Business::ownedBy($r->attributes->get('user_id'))->with('links')->findOrFail($business);$url=$r->input('url') ?: optional($b->links->firstWhere('link_type','website'))->url;$r->merge(['url'=>$url]);$url=$r->validate(['url'=>['required','url:http,https','max:2048']])['url'];$this->assertPublicHost($url);$start=microtime(true);try{$res=Http::timeout(12)->withOptions(['allow_redirects'=>false])->get($url);$code=$res->status();$data=['status'=>$res->successful()?'online':'degraded','http_status_code'=>$code,'response_time_ms'=>(int)((microtime(true)-$start)*1000),'error_message'=>null];}catch(\Throwable $e){$data=['status'=>'offline','http_status_code'=>null,'response_time_ms'=>(int)((microtime(true)-$start)*1000),'error_message'=>(string)str($e->getMessage())->limit(500)];}$check=$b->websiteChecks()->create($data+['user_id'=>$r->attributes->get('user_id'),'checked_at'=>now()]);return response()->json($check,201);}
 private function assertPublicHost(string $url):void{$host=parse_url($url,PHP_URL_HOST);$ips=filter_var($host,FILTER_VALIDATE_IP)?[$host]:gethostbynamel($host);if(!$ips)throw ValidationException::withMessages(['url'=>'The host could not be resolved.']);foreach($ips as $ip)if(!filter_var($ip,FILTER_VALIDATE_IP,FILTER_FLAG_NO_PRIV_RANGE|FILTER_FLAG_NO_RES_RANGE))throw ValidationException::withMessages(['url'=>'Private or reserved network addresses are not allowed.']);}
}
